server {
    listen 8443 ssl;
    server_name localhost;

    ssl_certificate /etc/nginx/ssl/nginx.crt;
    ssl_certificate_key /etc/nginx/ssl/nginx.key;

    # Main branch - serve at root
    location = /index.html {
        root /git/project-main;
        try_files /index.html =404;
    }

    # Dev branch - serve at /dev/
    location = /dev/index.html {
        alias /git/project-dev/index.html;
        try_files $uri =404;
    }

    # Default location
    location / {
        return 404;
    }
}

